--

-- Name: create_direct_chat(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_direct_chat(p_peer_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_me uuid := auth.uid();
    v_chat_id uuid;
    v_reused boolean := true;
BEGIN
    IF v_me IS NULL THEN
        RAISE EXCEPTION 'Not authorized';
    END IF;
    IF p_peer_id = v_me THEN
        RAISE EXCEPTION 'Cannot chat with yourself';
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM public.users
        WHERE id = p_peer_id AND deleted_at IS NULL
    ) THEN
        RAISE EXCEPTION 'Peer not found';
    END IF;

    -- Reuse an existing direct chat between the pair (1:1 chats are unique
    -- per pair — no duplicate threads).
    SELECT c.id INTO v_chat_id
    FROM public.chats c
    WHERE c.type = 'direct'
      AND EXISTS (
          SELECT 1 FROM public.chat_participants p1
          WHERE p1.chat_id = c.id AND p1.user_id = v_me
      )
      AND EXISTS (
          SELECT 1 FROM public.chat_participants p2
          WHERE p2.chat_id = c.id AND p2.user_id = p_peer_id
      )
    LIMIT 1;

    IF v_chat_id IS NULL THEN
        v_reused := false;
        INSERT INTO public.chats (type, reference_id)
        VALUES ('direct'::public.chat_type, NULL)
        RETURNING id INTO v_chat_id;

        INSERT INTO public.chat_participants (chat_id, user_id)
        VALUES (v_chat_id, v_me), (v_chat_id, p_peer_id);
    END IF;

    RETURN jsonb_build_object(
        'chatId', v_chat_id,
        'reused', v_reused
    );
END;
$$;


--

-- Name: is_chat_participant(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_chat_participant(p_chat_id uuid, p_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
    SELECT EXISTS (
        SELECT 1 FROM public.chat_participants
        WHERE chat_id = p_chat_id AND user_id = p_user_id
    );
$$;


--

-- Name: sync_group_chat_participant(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_group_chat_participant() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_chat_id uuid;
BEGIN
    -- plpgsql does NOT short-circuit AND/OR conditions, so each TG_OP gets its
    -- own branch with an explicit RETURN (pattern: OPT-009, migration
    -- 20260816000001). Only OLD is valid in the DELETE branch.
    IF TG_OP = 'DELETE' THEN
        SELECT id INTO v_chat_id
        FROM public.chats
        WHERE type = 'group' AND reference_id = OLD.group_id
        LIMIT 1;

        IF v_chat_id IS NOT NULL THEN
            DELETE FROM public.chat_participants
            WHERE chat_id = v_chat_id AND user_id = OLD.user_id;
        END IF;
        RETURN OLD;
    END IF;

    -- INSERT / UPDATE: resolve the group's chat row; no chat → no-op.
    SELECT id INTO v_chat_id
    FROM public.chats
    WHERE type = 'group' AND reference_id = NEW.group_id
    LIMIT 1;

    IF v_chat_id IS NULL THEN
        RETURN NEW;
    END IF;

    -- Active membership ⇒ participant row; invited/removed ⇒ none.
    IF NEW.status = 'active' THEN
        INSERT INTO public.chat_participants (chat_id, user_id)
        VALUES (v_chat_id, NEW.user_id)
        ON CONFLICT DO NOTHING;
    ELSE
        DELETE FROM public.chat_participants
        WHERE chat_id = v_chat_id AND user_id = NEW.user_id;
    END IF;

    RETURN NEW;
END;
$$;


--

-- Name: sync_group_chat_participants_on_chats(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_group_chat_participants_on_chats() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
    IF TG_OP = 'INSERT' AND NEW.type = 'group' THEN
        INSERT INTO public.chat_participants (chat_id, user_id)
        SELECT NEW.id, gm.user_id
        FROM public.group_members gm
        WHERE gm.group_id = NEW.reference_id AND gm.status = 'active'
        ON CONFLICT DO NOTHING;
    END IF;
    RETURN NEW;
END;
$$;


--

-- Name: group_members sync_group_chat_participant_trigger; Type: TRIGGER; Schema: public; Owner: -
--

CREATE TRIGGER sync_group_chat_participant_trigger AFTER INSERT OR DELETE OR UPDATE ON public.group_members FOR EACH ROW EXECUTE FUNCTION public.sync_group_chat_participant();


