-- Name: chats sync_group_chat_participants_on_chats_trigger; Type: TRIGGER; Schema: public; Owner: -
--

CREATE TRIGGER sync_group_chat_participants_on_chats_trigger AFTER INSERT ON public.chats FOR EACH ROW EXECUTE FUNCTION public.sync_group_chat_participants_on_chats();


