   FROM public.events
  WHERE ((events.id = chats.reference_id) AND (events.created_by_user_id = auth.uid()))))) OR ((type = 'group'::public.chat_type) AND (EXISTS ( SELECT 1
   FROM public.groups
  WHERE ((groups.id = chats.reference_id) AND (groups.created_by_user_id = auth.uid()))))) OR ((type = 'direct'::public.chat_type) AND (auth.uid() IN ( SELECT chat_participants.user_id
   FROM public.chat_participants
